const clinicas = $input.all();

if (clinicas.length === 0) {
  return [{ json: { query: null, mensaje: 'No hay clínicas activas' } }];
}

// Generar UNION ALL para traer leads de todas las clínicas con su clinica_id
const queries = clinicas.map(c => {
  const schema = c.json.schema_name;
  return `SELECT '${c.json.clinica_id}' as clinica_id, '${schema}' as schema_name, * FROM ${schema}.conversaciones`;
});

const query = queries.join(' UNION ALL ') + ';';

return [{ json: { query } }];

const leads_todos = $input.all();
const clinicas = $('Cargar clínicas activas').all();
const ahora = new Date();

// Calcular rango de la semana anterior (lunes a domingo)
const lunes_pasado = new Date(ahora);
lunes_pasado.setDate(ahora.getDate() - 7);
lunes_pasado.setHours(0, 0, 0, 0);

const domingo_pasado = new Date(ahora);
domingo_pasado.setDate(ahora.getDate() - 1);
domingo_pasado.setHours(23, 59, 59, 999);

const fecha_reporte = ahora.toLocaleDateString('es-CO', {
  day: 'numeric',
  month: 'long',
  year: 'numeric'
});

const periodo = `${lunes_pasado.toLocaleDateString('es-CO')} - ${domingo_pasado.toLocaleDateString('es-CO')}`;

// Agrupar leads por clinica_id
const leadsPorClinica = {};
leads_todos.forEach(lead => {
  const cid = lead.json.clinica_id;
  if (!leadsPorClinica[cid]) leadsPorClinica[cid] = [];
  leadsPorClinica[cid].push(lead.json);
});

// Generar un item por clínica con sus métricas
const resultados = [];

for (const clinica of clinicas) {
  const c = clinica.json;
  const cid = c.clinica_id;
  const leads = leadsPorClinica[cid] || [];

  // Filtrar por semana pasada
  const leads_semana = leads.filter(l => {
    if (!l.fecha_inicio) return false;
    const fecha = new Date(l.fecha_inicio);
    return fecha >= lunes_pasado && fecha <= domingo_pasado;
  });

  const total = leads_semana.length;
  const calificados = leads_semana.filter(l => l.calificado === true || l.calificado === 'TRUE').length;
  const agendados = leads_semana.filter(l => l.estado === 'agendado').length;
  const escalados = leads_semana.filter(l => l.estado === 'escalado').length;
  const frios = leads_semana.filter(l => l.estado === 'frio').length;
  const en_proceso = leads_semana.filter(l => l.estado === 'calificando' || l.estado === 'nuevo').length;

  const tasa_agendamiento = total > 0 ? Math.round((agendados / total) * 100) : 0;

  // Top tratamientos
  const tratamientos = {};
  leads_semana.forEach(l => {
    const t = l.tratamiento_interes;
    if (t && t !== 'null' && t !== '') {
      tratamientos[t] = (tratamientos[t] || 0) + 1;
    }
  });

  const top_tratamientos = Object.entries(tratamientos)
    .sort((a, b) => b[1] - a[1])
    .slice(0, 3)
    .map(([nombre, count]) => `${nombre} (${count})`)
    .join(', ') || 'Sin datos';

  resultados.push({
    json: {
      clinica_id: cid,
      nombre_clinica: c.nombre_clinica,
      wa_dueno_numero: c.wa_dueno_numero,
      llm_api_key: c.llm_api_key,
      llm_model: c.llm_model,
      evolution_instance: c.evolution_instance,
      evolution_api_key: c.evolution_api_key,
      schema_name: c.schema_name,
      fecha_reporte,
      periodo,
      total_leads: total,
      calificados,
      agendados,
      escalados,
      frios,
      en_proceso,
      tasa_agendamiento,
      top_tratamientos
    }
  });
}

return resultados;

const respuesta_llm = $input.first().json.choices[0].message.content;

// Obtener las métricas del item correspondiente usando pairedItem
// El item actual tiene los datos del LLM, pero necesitamos cruzarlo con las métricas
const itemIndex = $input.first().pairedItem?.item ?? 0;
const metricas_items = $('Calcular métricas por clínica').all();
const metricas_item = metricas_items[itemIndex]?.json || {};

const mensaje_completo = `📊 *Reporte Semanal LeadAI*
🏥 ${metricas_item.nombre_clinica}
📅 ${metricas_item.fecha_reporte}

${respuesta_llm}

━━━━━━━━━━━━━━━
📈 *Resumen rápido:*
- Leads totales: ${metricas_item.total_leads}
- Citas agendadas: ${metricas_item.agendados}
- Tasa de conversión: ${metricas_item.tasa_agendamiento}%
- Top tratamientos: ${metricas_item.top_tratamientos}`;

return [{
  json: {
    mensaje_completo,
    wa_dueno_numero: metricas_item.wa_dueno_numero,
    evolution_instance: metricas_item.evolution_instance,
    evolution_api_key: metricas_item.evolution_api_key,
    schema_name: metricas_item.schema_name,
    metricas: metricas_item
  }
}];

